function prepareGalleryClip() {
  const next = galleryTarget(true);
  if (next && next !== previewCard) pageVideos.prepare('gallery', galleryVideo, next.dataset.path + '-hd.mp4');
}
for (const event of ['playing', 'progress', 'timeupdate']) galleryVideo.addEventListener(event, prepareGalleryClip);
galleryVideo.addEventListener('ended', () => syncPreview(true));
function makeCard(example) {
  const card = document.createElement('button');
  card.type = 'button';
  card.className = 'gallery-card';
  card.id = 'clip-' + example.id;
  card.dataset.case = example.id;
  card.dataset.path = example.path;
  card.setAttribute('aria-haspopup','dialog');
  const picture = document.createElement('span');
  picture.className = 'gallery-picture';
  const img = new Image();
  img.decoding = 'async';
  img.alt = '';
  img.dataset.src = example.path + '-thumb.webp';
  const play = document.createElement('span');
  play.className = 'gallery-action';
  play.setAttribute('aria-hidden','true');
  const icon = document.createElement('i');
  icon.className = 'play-icon';
  play.append(icon);
  picture.append(img,play);
  const label = document.createElement('span');
  label.className = 'card-meta';
  label.textContent = example.category;
  const title = document.createElement('strong');
  title.textContent = example.title;
  card.append(picture,label,title);
  card.addEventListener('pointerenter', event => {
    if (event.pointerType === 'touch' || !hoverInput.matches) return;
    pointedCard = card;
    syncPreview();
  });
  card.addEventListener('pointerleave', () => { if (pointedCard === card) pointedCard = undefined; });
  card.addEventListener('focus', () => {
    if (card.matches(':focus-visible')) { focusedCard = card; syncPreview(); }
  });
  card.addEventListener('blur', () => { if (focusedCard === card) focusedCard = undefined; });
  card.addEventListener('click', () => { stopPreview(); openClip(example); });
  return card;
}
const cards = showcaseExamples.map(makeCard);
grid.append(...cards);
pageVideos.register('gallery', grid);
const nearbyPosters = new IntersectionObserver(entries => {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    const img = entry.target.querySelector('img');
    img.src = img.dataset.src;
    nearbyPosters.unobserve(entry.target);
  }
}, {rootMargin:'240px 0px'});
cards.forEach(card => nearbyPosters.observe(card));
const galleryObserver = new IntersectionObserver(entries => {
  for (const entry of entries) {
    const card = entry.target.closest('.gallery-card');
    if (entry.intersectionRatio >= .25) visibleCases.add(card);
    else visibleCases.delete(card);
  }
  syncPreview();
}, {threshold: [0, .25], rootMargin: '-54px 0px 0px'});
cards.forEach(card => galleryObserver.observe(card.querySelector('.gallery-picture')));
document.addEventListener('previewchange', () => syncPreview());
document.addEventListener('motionchange', () => syncPreview());
reducedMotion.addEventListener('change', () => syncPreview());
function filterGallery() {
  stopPreview();
  const matched = showcaseExamples.filter(item => galleryFilter === 'all' || item.group === galleryFilter);
  cards.forEach((card, i) => { card.hidden = !matched.includes(showcaseExamples[i]); });
  document.querySelector('#gallery-count').textContent = matched.length + (matched.length === 1 ? ' clip' : ' clips');
  syncPreview();
}
for (const button of document.querySelectorAll('[data-filter]')) {
  button.addEventListener('click', () => {
    galleryFilter = button.dataset.filter;
    for (const choice of document.querySelectorAll('[data-filter]')) choice.setAttribute('aria-pressed', choice === button);
    filterGallery();
  });
}
filterGallery();

for (const link of document.querySelectorAll('a[data-film-title]')) {
  link.addEventListener('click', event => {
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
    event.preventDefault();
    pageVideos.attach(film, link.getAttribute('href'));
    document.querySelector('#film-title').textContent = 'EraseAnything · ' + link.dataset.filmTitle;
    filmDialog.showModal();
    film.play().catch(() => {});
  });
}
filmDialog.addEventListener('close', () => { if (!filmDialog.open) pageVideos.release(film); });
let hiddenPlayback;
document.addEventListener('visibilitychange', () => {
  if (document.hidden) {
    const media = filmDialog.open ? film : clipDialog.open ? video : undefined;
    const path = media && pageVideos.source(media);
    if (path) {
      hiddenPlayback = {media, path, playing:pageVideos.playing(media)};
      pageVideos.release(media);
    }
  } else if (hiddenPlayback) {
    const {media, path, playing} = hiddenPlayback;
    hiddenPlayback = undefined;
    if (media.closest('dialog').open) {
      pageVideos.attach(media, path);
      if (playing) media.play().catch(() => {});
    }
  }
});
for (const dialog of document.querySelectorAll('dialog')) {
  dialog.addEventListener('click', event => {
    if (event.target !== dialog) return;
    const b = dialog.getBoundingClientRect();
    if (event.clientX < b.left || event.clientX > b.right || event.clientY < b.top || event.clientY > b.bottom) dialog.close();
  });
}
const mobileSections = document.querySelector('.mobile-sections');
mobileSections.querySelector('nav').addEventListener('click', () => { mobileSections.open = false; });
const readProgress = document.querySelector('.read-progress');
function updateProgress() {
  const scrollRange = document.documentElement.scrollHeight - window.innerHeight;
  readProgress.style.transform = 'scaleX(' + (scrollRange ? Math.min(1,window.scrollY / scrollRange) : 0) + ')';
}
window.addEventListener('scroll', updateProgress, {passive:true});
window.addEventListener('resize', updateProgress);
updateProgress();

const figureDialog = document.querySelector('#figure-dialog');
const enlargedFigure = document.querySelector('#enlarged-figure');

const nearbyFigures = new IntersectionObserver(entries => {
  for (const entry of entries) {
    if (!entry.isIntersecting) continue;
    const image = entry.target;
    image.src = image.dataset.figureSrc;
    nearbyFigures.unobserve(image);
  }
}, {rootMargin:'80px 0px'});
document.querySelectorAll('[data-figure-src]').forEach(image => nearbyFigures.observe(image));

for (const button of document.querySelectorAll('[data-figure]')) {
  button.addEventListener('click', () => {
    document.querySelector('#figure-title').textContent = button.dataset.title;
    enlargedFigure.src = button.dataset.figure;
    enlargedFigure.alt = button.dataset.alt ?? button.querySelector('img').alt;
    figureDialog.showModal();
  });
}

const copy = document.querySelector('#copy-citation');
let resetCopyLabel;
copy.addEventListener('click', async () => {
  const code = document.querySelector('#bibtex');
  const status = document.querySelector('#copy-status');
  clearTimeout(resetCopyLabel);
  try {
    await navigator.clipboard.writeText(code.textContent);
    copy.textContent = 'Copied';
    status.textContent = 'BibTeX copied to clipboard.';
    resetCopyLabel = setTimeout(() => { copy.textContent = 'Copy BibTeX'; }, 1800);
  } catch {
    const range = document.createRange();
    range.selectNodeContents(code);
    const selection = window.getSelection();
    selection.removeAllRanges();
    selection.addRange(range);
    status.textContent = 'BibTeX selected. Use your browser’s copy shortcut.';
    copy.textContent = 'BibTeX selected';
    resetCopyLabel = setTimeout(() => { copy.textContent = 'Copy BibTeX'; }, 3200);
  }
});

;
/* method-motion.js */
(() => {
  const get = id => document.getElementById(id);
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const figures = [...document.querySelectorAll('dialog')];
  const players = [];

  function makePlayer({panel, control, labels, advance, interval, firstStep}) {
    let visible = false;
    let manualHold = false;
    let explicitPlay = false;
    let timeout;
    let playing = false;

    function cancel() {
      clearTimeout(timeout);
      timeout = undefined;
    }

    function refresh() {
      const motionAllowed = !document.documentElement.classList.contains('motion-paused');
      const active = visible && !document.hidden && !figures.some(dialog => dialog.open) &&
        !manualHold && ((motionAllowed && !reduced.matches) || explicitPlay);
      if (active && timeout === undefined) {
        firstStep?.();
        const delay = interval();
        panel.style.setProperty('--tick-length', delay + 'ms');
        timeout = setTimeout(() => {
          timeout = undefined;
          advance();
          refresh();
        }, delay);
      } else if (!active) {
        cancel();
      }
      playing = active;
      panel.classList.toggle('motion-running', active);
      control.textContent = active ? labels.pause : labels.play;
    }

    function hold() {
      manualHold = true;
      explicitPlay = false;
      refresh();
    }

    control.addEventListener('click', () => {
      if (playing) { hold(); return; }
      manualHold = false;
      explicitPlay = true;
      refresh();
    });

    new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting && entry.intersectionRatio >= .18;
      refresh();
    }, {threshold: [0, .18], rootMargin: '-4% 0px -4% 0px'}).observe(panel);

    const restartClock = () => { cancel(); refresh(); };
    players.push({refresh, preferenceChanged() { explicitPlay = false; refresh(); }});
    refresh();
    return {hold, restartClock};
  }

  const trajectory = get('trajectory-frames');
  const trajectoryCard = trajectory.closest('.trajectory-card');
  const atlasObserver = new IntersectionObserver(([entry]) => {
    if (entry.isIntersecting) showAtlas();
  }, {rootMargin:'240px 0px'});
  function showAtlas() {
    trajectoryCard.dataset.atlasReady = '';
    atlasObserver.disconnect();
  }
  atlasObserver.observe(trajectoryCard);
  const steps = [...trajectoryCard.querySelectorAll('[data-step]')];
  const taskButtons = [...trajectoryCard.querySelectorAll('[data-trajectory-task]')];
  const stateImage = get('state-image');
  const estimateImage = get('estimate-image');
  const names = {object: 'Park pedestrian · Mask guided', overlay: 'Dog in the park · Text instruction'};
  const sigmas = ['1.000', '0.938', '0.834', '0.628', '0.000'];
  let currentStep = 0;
  function tile(index) {
    return (index % 3) * 50 + '% ' + Math.floor(index / 3) * 50 + '%';
  }
  steps.forEach((button, i) => {
    const thumbnail = document.createElement('span');
    thumbnail.className = 'step-thumbnail';
    thumbnail.setAttribute('aria-hidden', 'true');
    thumbnail.style.backgroundPosition = tile(i);
    button.prepend(thumbnail);
  });

  function displayStep(next) {
    currentStep = next;
    const source = next === 0;
    stateImage.style.backgroundPosition = tile(next);
    estimateImage.style.backgroundPosition = tile(source ? 0 : next + 4);
    stateImage.setAttribute('aria-label', source ? 'Source frame' : 'Decoded sampler state after update ' + next);
    estimateImage.setAttribute('aria-label', source ? 'Source frame' : 'Predicted clean image at update ' + next);
    stateImage.nextElementSibling.textContent = source ? 'Source frame' : 'Updated sampler state';
    estimateImage.nextElementSibling.textContent = source ? 'Source frame' : 'Predicted clean frame';
    steps.forEach((button, i) => button.setAttribute('aria-pressed', String(i === next)));
    trajectoryCard.dataset.task = trajectory.dataset.task;
    get('trajectory-note').textContent = names[trajectory.dataset.task] + (source ? ' · Source frame 109' :
      ' · Update ' + next + ' · Noise level ' + sigmas[next]) + (next === 4 ? ' · Both views match the final result.' : '');
  }

  displayStep(0);
  const trajectoryPlayer = makePlayer({
    panel: trajectoryCard, control: get('replay-trajectory'),
    labels: {play: 'Play updates', pause: 'Pause updates'},
    advance: () => displayStep((currentStep + 1) % steps.length),
    interval: () => currentStep === 4 ? 2450 : 1300
  });
  steps.forEach((button, i) => button.addEventListener('click', () => {
    showAtlas();
    trajectoryPlayer.hold();
    displayStep(i);
  }));
  taskButtons.forEach(button => button.addEventListener('click', () => {
    trajectory.dataset.task = button.dataset.trajectoryTask;
    showAtlas();
    taskButtons.forEach(item => item.setAttribute('aria-pressed', String(item === button)));
    displayStep(currentStep);
    trajectoryPlayer.restartClock();
  }));

  const method = document.querySelector('.method-tour');
  const spot = method.querySelector('.method-spot');
  const stageButtons = [...method.querySelectorAll('[data-method-stage]')];
  const stages = [
    {bounds: [3.3, 2.4, 93.5, 36.1], caption: 'Condition encoding turns the instruction, source video, and spatial cue into context for the generator.'},
    {bounds: [3.3, 39.1, 66.5, 32.3], caption: 'In each DiT block, the noisy target reads source and cue features through asymmetric attention.'},
    {bounds: [70.5, 39.1, 26.2, 32.3], caption: 'Four Euler updates refine the target state. The decoder maps the final state back to video frames.'}
  ];
  let currentStage = -1;
  function showStage(i) {
    const {bounds, caption} = stages[i];
    currentStage = i;
    spot.hidden = false;
    ['left', 'top', 'width', 'height'].forEach((key, n) => { spot.style[key] = bounds[n] + '%'; });
    stageButtons.forEach((button, n) => button.setAttribute('aria-pressed', String(i === n)));
    get('method-tour-caption').textContent = caption;
  }
  get('method-controls').hidden = false;
  stageButtons.forEach(button => button.setAttribute('aria-pressed', 'false'));
  const methodPlayer = makePlayer({
    panel: method, control: get('play-method-tour'),
    labels: {play: 'Play tour', pause: 'Pause tour'},
    advance: () => showStage((currentStage + 1) % stages.length),
    interval: () => 2950,
    firstStep: () => { if (currentStage < 0) showStage(0); }
  });
  stageButtons.forEach((button, i) => button.addEventListener('click', () => {
    methodPlayer.hold();
    showStage(i);
  }));
  const refresh = () => players.forEach(player => player.refresh());
  document.addEventListener('visibilitychange', refresh);
  const preferenceChanged = () => players.forEach(player => player.preferenceChanged());
  document.addEventListener('motionchange', preferenceChanged);
  reduced.addEventListener('change', preferenceChanged);
  const dialogObserver = new MutationObserver(refresh);
  figures.forEach(dialog => dialogObserver.observe(dialog, {attributes: true, attributeFilter: ['open']}));
})();
